use std::borrow::Cow;

pub fn normalize_whitespace_normal(text: &str) -> Cow<'_, str> {
    // Collapse runs of [ \t\n\r\f]+ to a single space, strip leading/trailing spaces.
    // If the input already satisfies this, return it borrowed.
    let mut result = String::with_capacity(text.len());
    let mut in_ws = false;
    let mut changed = false;
    for ch in text.chars() {
        if ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r' || ch == '\x0C' {
            in_ws = true;
            changed = true;
        } else {
            if in_ws && !result.is_empty() {
                result.push(' ');
            }
            in_ws = false;
            result.push(ch);
        }
    }
    if !changed {
        Cow::Borrowed(text)
    } else {
        Cow::Owned(result)
    }
}

pub fn normalize_whitespace_pre_wrap(text: &str) -> Cow<'_, str> {
    let mut result = String::with_capacity(text.len());
    let mut chars = text.chars().peekable();
    let mut changed = false;
    while let Some(ch) = chars.next() {
        if ch == '\r' {
            changed = true;
            // Consume all consecutive \r and at most one following \n
            // so that \r\r\n produces a single \n instead of double.
            while chars.peek() == Some(&'\r') {
                chars.next();
            }
            if chars.peek() == Some(&'\n') {
                chars.next();
            }
            result.push('\n');
        } else if ch == '\x0C' {
            changed = true;
            result.push('\n');
        } else {
            result.push(ch);
        }
    }
    if !changed {
        Cow::Borrowed(text)
    } else {
        Cow::Owned(result)
    }
}
